@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelList Channels="channels"
                 ActiveChannelId="selectedChannel?.Id"
                 OnChannelSelected="SelectChannel" />

    <div class="chat-main @(threadOpen ? "thread-visible" : "")">
        @if (selectedChannel is not null)
        {
            <MessageArea Channel="selectedChannel"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         IsLoadingMore="isLoadingMore"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReact"
                         OnReactionSelected="HandleReactionSelected"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadOpen && threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private Channel? selectedChannel;
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private bool isLoadingMore;

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        threadSummaries = BuildThreadSummaries(messages);
        CloseThread();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to update unread counts
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;

        isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (olderMessages.Count > 0)
        {
            messages.InsertRange(0, olderMessages);
            threadSummaries = BuildThreadSummaries(messages);
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;

        var newMessage = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(newMessage);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary in main view
        threadSummaries = BuildThreadSummaries(messages, threadRootMessage.Id, threadReplies.Count);
    }

    private async Task HandleReact(int messageId)
    {
        // Default reaction when clicking existing badge
        await ChatService.AddReactionAsync(messageId, "👍");
    }

    private async Task HandleReactionSelected((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
        }
    }

    private List<ThreadSummary> BuildThreadSummaries(List<Message> msgs, int? updatedThreadId = null, int? updatedCount = null)
    {
        var summaries = new List<ThreadSummary>();
        var rootIds = msgs.Where(m => m.ReplyToId is null).Select(m => m.Id).ToHashSet();
        var replies = msgs.Where(m => m.ReplyToId is not null && rootIds.Contains(m.ReplyToId.Value));

        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            summaries.Add(new ThreadSummary(group.Key, group.Count(), group.Max(m => m.SentAt)));
        }

        // Include updated thread info if we have it
        if (updatedThreadId.HasValue && updatedCount.HasValue)
        {
            var existing = summaries.FirstOrDefault(s => s.RootMessageId == updatedThreadId.Value);
            if (existing is null)
            {
                summaries.Add(new ThreadSummary(updatedThreadId.Value, updatedCount.Value, DateTime.Now));
            }
        }

        return summaries;
    }
}

