    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

.channel-list-header {
    padding: 1rem;
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #949ba4;
    border-bottom: 1px solid #1e1f22;
    margin: 0;
}

.channel-list-items {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    position: relative;
}

.channel-item:hover {
    background: #35373c;
    color: #dbdee1;
}

.channel-item.active {
    background: #404249;
    color: #fff;
}

.channel-name {
    font-weight: 500;
    font-size: 0.9rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 8px;
    min-width: 16px;
    text-align: center;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.thread-visible {
    flex: 0 0 55%;
}

.message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    background: #313338;
    color: #dbdee1;
}

.message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
}

.loading-indicator {
    text-align: center;
    color: #949ba4;
    padding: 0.5rem;
    font-size: 0.8rem;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #949ba4;
}

/* Message Item */
.message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    position: relative;
    margin-bottom: 0.25rem;
}

.message-item:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

.message-content {
    margin-top: 0.2rem;
    font-size: 0.9rem;
    line-height: 1.4;
    word-break: break-word;
}

.message-reactions {
    display: flex;
    gap: 0.3rem;
    margin-top: 0.3rem;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.1rem 0.4rem;
    font-size: 0.8rem;
    cursor: pointer;
}

.reaction-badge:hover {
    border-color: #5865f2;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.2rem;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.2rem;
}

.action-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
}

.action-btn:hover {
    background: #404249;
    color: #fff;
}

.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.2rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 0.4rem;
    z-index: 10;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 4px;
}

.emoji-btn:hover {
    background: #404249;
}

/* Message Input */
.message-input {
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-input textarea {
    flex: 1;
    resize: none;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 1rem;
    color: #dbdee1;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
}

.message-input textarea:focus {
    box-shadow: 0 0 0 1px #5865f2;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 0.6rem 1rem;
    font-size: 0.85rem;
    font-weight: 500;
    cursor: pointer;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 250px;
    background: #2b2d31;
    color: #dbdee1;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
}

.close-btn:hover {
    background: #404249;
    color: #fff;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #949ba4;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
}

.thread-reply {
    margin-bottom: 0.75rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #3f4147;
}

.thread-reply:last-child {
    border-bottom: none;
}

