+    border: 1px solid #3f4147;
+    border-radius: 6px;
+    padding: 0.4rem;
+    z-index: 10;
+}
+
+.emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem;
+    border-radius: 4px;
+}
+
+.emoji-btn:hover {
+    background: #404249;
+}
+
+/* Message Input */
+.message-input {
+    padding: 0.75rem 1rem;
+    border-top: 1px solid #3f4147;
+    display: flex;
+    gap: 0.5rem;
+    align-items: flex-end;
+    flex-shrink: 0;
+}
+
+.message-input textarea {
+    flex: 1;
+    resize: none;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 1rem;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+}
+
+.message-input textarea:focus {
+    box-shadow: 0 0 0 1px #5865f2;
+}
+
+.send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 0.6rem 1rem;
+    font-size: 0.85rem;
+    font-weight: 500;
+    cursor: pointer;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 250px;
+    background: #2b2d31;
+    color: #dbdee1;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #1e1f22;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #404249;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+    background: #232428;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    color: #949ba4;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+}
+
+.thread-reply {
+    margin-bottom: 0.75rem;
+    padding-bottom: 0.5rem;
+    border-bottom: 1px solid #3f4147;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
+

